import java.util.*;

class BSTIterator {
  private final Deque<TreeNode> stack = new ArrayDeque<>();
  private final List<Integer> seen = new ArrayList<>(); // values visited so far, in order
  private int pos = -1;

  public BSTIterator(TreeNode root) {
    pushLeft(root);
  }

  public boolean hasNext() {
    return pos + 1 < seen.size() || !stack.isEmpty();
  }

  public int next() {
    pos++;
    if (pos == seen.size()) { // advance the real traversal only when needed
      TreeNode node = stack.pop();
      pushLeft(node.right);
      seen.add(node.val);
    }
    return seen.get(pos);
  }

  public boolean hasPrev() {
    return pos > 0;
  }

  public int prev() {
    return seen.get(--pos);
  }

  private void pushLeft(TreeNode node) {
    for (; node != null; node = node.left) stack.push(node);
  }
}
